fn put(o:&mut[u8],p:usize,x:f64){o[p..p+8].copy_from_slice(&x.to_le_bytes());}
#[no_mangle]
pub unsafe extern "C" fn gauss_jordan(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<2||n>22{return -1}let x=std::slice::from_raw_parts(v,n);let(r,c)=(x[0],x[1]);if !(1..=4).contains(&r)||!(1..=4).contains(&c)||n!=2+(r*c+r)as usize{return -1}let(r,c)=(r as usize,c as usize);let mut a=[[0.0f64;4];4];let mut b=[0.0f64;4];for i in 0..r{for j in 0..c{let z=x[2+i*c+j];if !(-5000..=5000).contains(&z){return -1}a[i][j]=z as f64/1000.0;}let z=x[2+r*c+i];if !(-5000..=5000).contains(&z){return -1}b[i]=z as f64/1000.0;}let count=r*c+r;let bytes=count*8;if out.is_null()||cap<bytes{return -2}for col in 0..c{let pivot=(col..r).find(|&row|a[row][col].abs()>1e-8);let Some(pivot)=pivot else{continue};if pivot!=col{a.swap(col,pivot);b.swap(col,pivot);}let pv=a[col][col];for j in 0..c{a[col][j]/=pv;}b[col]/=pv;for row in 0..r{if row==col{continue}let f=a[row][col];for j in 0..c{a[row][j]-=f*a[col][j];}b[row]-=f*b[col];}}let dst=std::slice::from_raw_parts_mut(out,bytes);let mut at=0;for i in 0..r{for j in 0..c{put(dst,at*8,a[i][j]);at+=1;}}for value in b.iter().take(r){put(dst,at*8,*value);at+=1;}bytes as i64}
